fn solve(coins: Vec<i8>) -> i8 {
    // Sum in a larger type to avoid overflow (max sum = 500)
    let total: i32 = coins.iter().map(|&c| c as i32).sum();

    // Check that the sum is strictly positive and divisible by 5
    if total > 0 && total % 5 == 0 {
        // Safe to cast back to i8 because the result is between 0 and 100
        (total / 5) as i8
    } else {
        -1
    }
}

fn main() {
    // Example usage:
    let coins = vec![10, 20, 30, 40, 0];
    let result = solve(coins);
    println!("{}", result); // prints 20
}